"/><circle cx=\"257\" cy=\"10\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"114\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"101\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"88\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"75\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"62\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"49\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"36\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"23\" r=\"2\" fill=\"#475569\"/><circle cx=\"270\" cy=\"10\" r=\"2\" fill=\"#475569\"/><line x1=\"6.1\" y1=\"62\" x2=\"273.9\" y2=\"62\" stroke=\"#1e293b\" stroke-width=\"1.8\"/><polygon points=\"273.9,62 264.9,57.5 264.9,66.5\" fill=\"#1e293b\"/><polygon points=\"6.1,62 15.1,66.5 15.1,57.5\" fill=\"#1e293b\"/><polygon points=\"23,62 75,62 49,88\" fill=\"#ffffff\" stroke=\"#1e293b\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><polygon points=\"23,62 49,62 36,75\" fill=\"#38bdf8\" stroke=\"#1e293b\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><polygon points=\"49,62 49,88 62,75\" fill=\"#38bdf8\" stroke=\"#1e293b\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><polygon points=\"205,62 244,62 205,23\" fill=\"#ffffff\" stroke=\"#1e293b\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><polygon points=\"205,62 224.5,62 205,42.5\" fill=\"#38bdf8\" stroke=\"#1e293b\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><polygon points=\"205,42.5 224.5,42.5 224.5,62\" fill=\"#38bdf8\" stroke=\"#1e293b\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><text x=\"279.9\" y=\"67\" font-size=\"13\" text-anchor=\"start\" fill=\"#1e293b\" font-weight=\"bold\" font-style=\"italic\">k</text></svg>"
